utral-umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Hurricane deductibles","Wind and flood claims","Nor’easter damage"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}],"priceRange":"$$"},{"@type":"WebSite","@id":"https://newjerseyinsuranceappraiser.com/#website","url":"https://newjerseyinsuranceappraiser.com/","name":"New Jersey Insurance Appraiser","publisher":{"@id":"https://newjerseyinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://newjerseyinsuranceappraiser.com/resource-center/glossary/#webpage","url":"https://newjerseyinsuranceappraiser.com/resource-center/glossary/","name":"Insurance Claim Glossary | ACV, RCV, Umpire & More","description":"Plain-English definitions of 40 property insurance claim terms: ACV, replacement cost, holdback, hurricane deductible, umpire, O&P and more.","inLanguage":"en-US","isPartOf":{"@id":"https://newjerseyinsuranceappraiser.com/#website"},"about":{"@id":"https://newjerseyinsuranceappraiser.com/#business"},"publisher":{"@id":"https://newjerseyinsuranceappraiser.com/#business"},"dateModified":"2026-11-12","primaryImageOfPage":{"@type":"ImageObject","@id":"https://newjerseyinsuranceappraiser.com/resource-center/glossary/#primaryimage","url":"https://newjerseyinsuranceappraiser.com/assets/img/photos/paperwork.webp","width":1200,"height":797},"breadcrumb":{"@id":"https://newjerseyinsuranceappraiser.com/resource-center/glossary/#breadcrumb"},"mainEntity":{"@id":"https://newjerseyinsuranceappraiser.com/resource-center/glossary/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://newjerseyinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Resources","item":"https://newjerseyinsuranceappraiser.com/resource-center/"},{"@type":"ListItem","position":3,"name":"Glossary","item":"https://newjerseyinsuranceappraiser.com/resource-center/glossary/"}],"@id":"https://newjerseyinsuranceappraiser.com/resource-center/glossary/#breadcrumb"},{"@type":"DefinedTermSet","name":"Property insurance claim glossary","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. Many policies pay ACV first and the rest after repairs."},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Coverage for extra costs of living elsewhere while your home is being repaired."},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of covered damage. It’s the question an appraisal panel decides."},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy provision that lets either side demand appraisal when they disagree on the amount of loss."},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision that sets the amount of loss, binding when signed by any two of the three panel members."},{"@type":"DefinedTerm","name":"Appraiser","description":"The person each side names to value the loss. Policies usually require a competent and disinterested appraiser."},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage for the house itself and attached structures."},{"@type":"DefinedTerm","name":"Coverage B","description":"Other-structures coverage for detached garages, sheds and fences."},{"@type":"DefinedTerm","name":"Coverage C","description":"Personal property coverage for contents."},{"@type":"DefinedTerm","name":"Coverage D","description":"Loss-of-use coverage, including additional living expenses."},{"@type":"DefinedTerm","name":"Debris removal","description":"Coverage for removing debris after a covered loss, often with separate limits for trees."},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of your policy listing limits, deductibles and endorsements."},{"@type":"DefinedTerm","name":"Deductible","description":"The part of a covered loss you pay before the policy pays."},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value for age and wear. Recoverable depreciation is paid after repairs under a replacement cost policy."},{"@type":"DefinedTerm","name":"DOBI","description":"The New Jersey Department of Banking and Insurance, the state’s insurance regulator."},{"@type":"DefinedTerm","name":"Endorsement","description":"A policy amendment that adds, removes or changes coverage."},{"@type":"DefinedTerm","name":"FAIR Plan","description":"A state-backed insurer of last resort. In New Jersey it’s the New Jersey Insurance Underwriting Association."},{"@type":"DefinedTerm","name":"Flood exclusion","description":"The homeowners policy provision that excludes surface water, storm surge and related flooding."},{"@type":"DefinedTerm","name":"Holdback","description":"Recoverable depreciation the insurer holds until repairs are completed."},{"@type":"DefinedTerm","name":"Hurricane deductible","description":"A separate deductible, often a percentage of Coverage A, that applies when the policy’s hurricane trigger is met."},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice at the eaves that traps meltwater, which can back up under shingles into the home."},{"@type":"DefinedTerm","name":"Line item","description":"A single priced entry in an estimate, such as one square of shingles."},{"@type":"DefinedTerm","name":"Matching","description":"Whether repaired areas must reasonably match undamaged areas in color, texture and style."},{"@type":"DefinedTerm","name":"Mitigation","description":"Steps taken to prevent further damage after a loss, such as tarping or drying."},{"@type":"DefinedTerm","name":"NFIP","description":"The National Flood Insurance Program, the federal program that writes most flood insurance."},{"@type":"DefinedTerm","name":"Nor’easter","description":"A coastal storm with northeast winds, common in New Jersey in fall and winter."},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for added costs of meeting building codes during repairs."},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor’s charge for coordinating a repair, often 10% plus 10%."},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, sometimes required by the insurer."},{"@type":"DefinedTerm","name":"Public adjuster","description":"A state-licensed professional who represents policyholders in handling and negotiating claims."},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with similar materials, without depreciation."},{"@type":"DefinedTerm","name":"Reservation of rights","description":"A letter in which the insurer investigates while reserving the right to deny coverage."},{"@type":"DefinedTerm","name":"Scope","description":"The list of damaged items and repairs included in an estimate."},{"@type":"DefinedTerm","name":"Square","description":"100 square feet of roof surface."},{"@type":"DefinedTerm","name":"Supplement","description":"A request to add items or costs to an existing estimate."},{"@type":"DefinedTerm","name":"Suit limitation","description":"The policy deadline for filing a lawsuit against the insurer, often 12 months in New Jersey."},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third panel member who decides items the appraisers can’t agree on."},{"@type":"DefinedTerm","name":"Uniform Construction Code (UCC)","description":"New Jersey’s statewide building code, which governs permits and repairs."},{"@type":"DefinedTerm","name":"Windstorm deductible","description":"A deductible that applies to wind losses generally, broader than a hurricane deductible."},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers and contractors to price repairs."}],"@id":"https://newjerseyinsuranceappraiser.com/resource-center/glossary/#definedtermset"}]}</script>
